          "starter": "REQUIRED = [\n    \"strict-transport-security\",\n    \"content-security-policy\",\n    \"x-content-type-options\",\n    \"x-frame-options\",\n]\n\ndef security_score(headers):\n    # твой код здесь\n    pass\n",
          "tests": "full = {\"strict-transport-security\": \"max-age=1\", \"content-security-policy\": \"default-src 'self'\", \"x-content-type-options\": \"nosniff\", \"x-frame-options\": \"DENY\"}\nassert security_score(full) == (4, \"A\"), \"все четыре — (4, 'A')\"\nthree = dict(full); del three[\"x-frame-options\"]\nassert security_score(three) == (3, \"B\"), \"три — оценка B\"\ntwo = {\"x-frame-options\": \"DENY\", \"x-content-type-options\": \"nosniff\", \"server\": \"nginx\"}\nassert security_score(two) == (2, \"C\"), \"два — оценка C (посторонние заголовки не считаются)\"\nassert security_score({\"x-frame-options\": \"DENY\"}) == (1, \"D\"), \"один — D\"\nassert security_score({}) == (0, \"D\"), \"ноль — D\"\n",
