          "kind": "code",
          "lang": "python",
          "caption": "site_checker.py — запускать у себя: python site_checker.py sites.txt",
          "code": "\"\"\"site_checker.py: проверка списка сайтов (статус, HTTPS, заголовки безопасности).\"\"\"\nimport csv\nimport sys\nimport time\n\nimport requests\n\nUSER_AGENT = \"school-site-checker/1.0 (learning project)\"\nREQUIRED_HEADERS = [\n    \"strict-transport-security\",\n    \"content-security-policy\",\n    \"x-content-type-options\",\n    \"x-frame-options\",\n]\n\n\ndef normalize_url(raw):\n    \"\"\"'example.com ' -> 'https://example.com'; пустая строка -> ''.\"\"\"\n    url = raw.strip()\n    if not url:\n        return \"\"\n    if \"://\" not in url:\n        url = \"https://\" + url\n    return url\n\n\ndef classify_status(code):\n    if code is None:\n        return \"no_response\"\n    if 200 <= code < 300:\n        return \"ok\"\n    if 300 <= code < 400:\n        return \"redirect\"\n    if 400 <= code < 500:\n        return \"client_error\"\n    if 500 <= code < 600:\n        return \"server_error\"\n    return \"unknown\"\n\n\ndef missing_headers(headers):\n    lowered = {name.lower() for name in headers}\n    return [h for h in REQUIRED_HEADERS if h not in lowered]\n\n\ndef check_site(url, timeout=5):\n    result = {\n        \"url\": url, \"status\": None, \"kind\": \"no_response\", \"final_url\": \"\",\n        \"https\": False, \"upgrades_to_https\": False, \"seconds\": None,\n        \"missing\": [], \"server\": \"\", \"error\": \"\",\n    }\n    try:\n        started = time.perf_counter()\n        resp = requests.get(url, timeout=timeout, headers={\"User-Agent\": USER_AGENT})\n        result[\"seconds\"] = round(time.perf_counter() - started, 2)\n    except requests.exceptions.SSLError:\n        result[\"error\"] = \"ошибка сертификата\"\n        return result\n    except requests.exceptions.Timeout:\n        result[\"error\"] = \"тайм-аут\"\n        return result\n    except requests.exceptions.RequestException as exc:\n        result[\"error\"] = type(exc).__name__\n        return result\n\n    result[\"status\"] = resp.status_code\n    result[\"kind\"] = classify_status(resp.status_code)\n    result[\"final_url\"] = resp.url\n    result[\"https\"] = resp.url.startswith(\"https://\")\n    result[\"upgrades_to_https\"] = url.startswith(\"http://\") and result[\"https\"]\n    result[\"missing\"] = missing_headers(resp.headers)\n    result[\"server\"] = resp.headers.get(\"Server\", \"\")\n    return result\n\n\ndef print_table(results):\n    print(f\"{'URL':<32} {'КОД':<5} {'HTTPS':<6} {'СЕК':<5} ЗАГОЛОВКИ (нет из 4)\")\n    for r in results:\n        status = r[\"status\"] if r[\"status\"] is not None else \"-\"\n        https = \"да\" if r[\"https\"] else \"нет\"\n        secs = r[\"seconds\"] if r[\"seconds\"] is not None else \"-\"\n        tail = r[\"error\"] or f\"{len(r['missing'])}\"\n        print(f\"{r['url'][:31]:<32} {str(status):<5} {https:<6} {str(secs):<5} {tail}\")\n\n\ndef save_csv(results, path=\"report.csv\"):\n    fields = [\"url\", \"status\", \"kind\", \"final_url\", \"https\", \"upgrades_to_https\",\n              \"seconds\", \"missing\", \"server\", \"error\"]\n    with open(path, \"w\", newline=\"\", encoding=\"utf-8\") as f:\n        writer = csv.DictWriter(f, fieldnames=fields)\n        writer.writeheader()\n        for r in results:\n            row = dict(r)\n            row[\"missing\"] = \";\".join(r[\"missing\"])\n            writer.writerow(row)\n\n\ndef main():\n    path = sys.argv[1] if len(sys.argv) > 1 else \"sites.txt\"\n    try:\n        with open(path, encoding=\"utf-8\") as f:\n            lines = [ln for ln in f if ln.strip() and not ln.strip().startswith(\"#\")]\n    except FileNotFoundError:\n        print(f\"Нет файла {path}. Создай его: по одному сайту в строке.\")\n        return\n    results = []\n    for line in lines:\n        url = normalize_url(line)\n        results.append(check_site(url))\n        time.sleep(1)                       # вежливая пауза между запросами\n    print_table(results)\n    save_csv(results)\n    bad = [r for r in results if r[\"kind\"] != \"ok\" or not r[\"https\"]]\n    print(f\"\\nВсего: {len(results)}, с проблемами: {len(bad)}. Отчёт: report.csv\")\n\n\nif __name__ == \"__main__\":\n    main()"
